from pathlib import Path
p=Path(__file__).parent/'site/assets'
colors=[('#c7ff48','#171813'),('#b7c1d8','#242c43'),('#ef997b','#382b24'),('#d9d9cb','#293329')]
for i,(bg,ink) in enumerate(colors):
 lines=''.join(f'<path d="M30 {y}h{200 if y%40 else 135}" stroke="{ink}" stroke-width="5" opacity=".5"/>' for y in range(90,350,28))
 grid=f'<defs><pattern id="halftone" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="{ink}" opacity=".3"/></pattern></defs><rect width="800" height="500" fill="url(#halftone)"/>'
 art=[f'<g transform="translate(240 20) rotate(12 140 210)"><path d="M0 0h245l35 40v390H0z" fill="#f4f1e8" stroke="{ink}" stroke-width="2"/>{lines}<path d="M30 63h120" stroke="{ink}" stroke-width="20"/></g><rect x="20" y="192" width="760" height="100" fill="{ink}" transform="rotate(-8 400 250)"/><text x="75" y="268" font-family="monospace" font-weight="bold" font-size="75" fill="{bg}" transform="rotate(-8 400 250)">PEDIDO → AÇÃO</text>',
 f'<g transform="translate(150 80) rotate(-12 160 160)"><rect width="260" height="350" fill="#f4f1e8" stroke="{ink}" stroke-width="3"/>{lines}</g><g transform="translate(430 65) rotate(12 160 160)"><rect width="260" height="350" fill="{ink}"/><path d="M40 80h175m-175 35h125m-125 35h175m-175 35h90" stroke="{bg}" stroke-width="12"/></g><path d="M335 280h140m-35-35 35 35-35 35" stroke="{bg}" stroke-width="20" fill="none"/>',
 f'<g transform="translate(370 240) rotate(-15)"><circle r="165" fill="#f4f1e8" stroke="{ink}" stroke-width="5"/><circle r="140" fill="none" stroke="{ink}" stroke-dasharray="2 23" stroke-width="18"/><path d="M0-105V0l85 55" stroke="{ink}" stroke-width="13" fill="none"/><circle r="13" fill="{ink}"/></g><rect x="430" y="295" width="330" height="80" fill="{ink}"/><text x="454" y="350" font-family="monospace" font-size="45" fill="{bg}">TEMPO / IA</text>',
 f'<path d="M120 390h560M120 390V95" stroke="{ink}" stroke-width="4"/><rect x="160" y="240" width="100" height="150" fill="{ink}"/><rect x="320" y="180" width="100" height="210" fill="{ink}"/><rect x="480" y="100" width="100" height="290" fill="{ink}"/><rect x="200" y="125" width="390" height="90" fill="#c7ff48" transform="rotate(-10 400 250)"/><text x="235" y="190" font-family="monospace" font-size="55" font-weight="bold" fill="{ink}" transform="rotate(-10 400 250)">CAPACIDADE</text>'][i]
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 500"><rect width="800" height="500" fill="{bg}"/>{grid}{art}<text x="25" y="474" font-family="monospace" font-size="12" fill="{ink}">LEGALOPS.NEWS / ILUSTRAÇÃO EDITORIAL / 0{i+1}</text></svg>'
 (p/f'news-{i}.svg').write_text(svg)
(p/'club-social.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><rect width="1080" height="1080" fill="#f7e2d9"/><text x="90" y="130" font-family="Space Grotesk, sans-serif" font-size="50" letter-spacing="-3" fill="#20211f">legalops<tspan fill="#a63d24">.</tspan>club</text><g font-family="Space Grotesk, sans-serif" font-size="110" letter-spacing="-6" fill="#20211f"><text x="90" y="430">seu próximo</text><text x="90" y="560">“e se?”</text><text x="90" y="690">começa aqui.</text></g><text x="90" y="970" font-family="sans-serif" font-size="18" letter-spacing="3" fill="#20211f">COMUNIDADE / LEGALOPS.CLUB</text><g fill="#f17e61"><rect x="800" y="810" width="80" height="80"/><rect x="890" y="900" width="80" height="80"/><rect x="980" y="810" width="80" height="80"/><rect x="890" y="720" width="80" height="80"/></g></svg>''')
